from collections import deque

def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0])
    # Colored markers are 3x3 squares or Xs. Ignore gray wires, gray crossings, and 9-obstacles.
    seen=set(); nodes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] in (0,5,8,9) or (r,c) in seen: continue
            color=g[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                a,b=q.pop(); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==color:
                        seen.add((x,y)); q.append((x,y))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            nodes.append({'color':color,'r':(min(rs)+max(rs))//2,'c':(min(cs)+max(cs))//2})
    # Turn every original marker into an X.
    for n in nodes:
        r,c,col=n['r'],n['c'],n['color']
        for dr in (-1,0,1):
            for dc in (-1,0,1): g[r+dr][c+dc]=0
        for dr,dc in ((-1,-1),(-1,1),(0,0),(1,-1),(1,1)): g[r+dr][c+dc]=col
    # Side-to-side tasks are the transpose of top-to-bottom tasks.
    rows=[n['r'] for n in nodes]; cols=[n['c'] for n in nodes]
    vertical=(max(rows)-min(rows) >= max(cols)-min(cols))
    # demo 1 has markers on left and right: columns differ more, so vertical=False.
    if vertical:
        top=min(rows); bottom=max(rows)
        maxwire=max((r for r in range(H) for c in range(W) if grid[r][c]==8),default=bottom-1)
        if bottom==top or bottom<maxwire: bottom=maxwire+1
        # If all nodes start on top, reserve the row immediately below the network.
        if all(n['r']==top for n in nodes): bottom=maxwire+1
        rungs=[]
        for r in range(H):
            c=0
            while c<W:
                if grid[r][c]==8:
                    s=c
                    while c<W and grid[r][c]==8: c+=1
                    if c-s>=2: rungs.append((r,s,c-1))
                else: c+=1
        partners=[]
        for n in nodes:
            r,c=n['r'],n['c']
            seq=rungs if r==top else list(reversed(rungs))
            for rr,a,b in seq:
                if min(r,bottom)<rr<max(r,bottom) or (rr>r and rr<bottom) or (rr<r and rr>bottom):
                    if c==a: c=b
                    elif c==b: c=a
            nr=bottom if r==top else top
            partners.append((nr,c,n['color']))
    else:
        left=min(cols); right=max(cols)
        maxwire=max((c for r in range(H) for c in range(W) if grid[r][c]==8),default=right-1)
        if all(n['c']==left for n in nodes): right=maxwire+1
        rungs=[]
        for c in range(W):
            r=0
            while r<H:
                if grid[r][c]==8:
                    s=r
                    while r<H and grid[r][c]==8: r+=1
                    if r-s>=2: rungs.append((c,s,r-1))
                else: r+=1
        partners=[]
        for n in nodes:
            r,c=n['r'],n['c']
            seq=rungs if c==left else list(reversed(rungs))
            for cc,a,b in seq:
                if (cc>c and cc<right) or (cc<c and cc>right):
                    if r==a: r=b
                    elif r==b: r=a
            nc=right if c==left else left
            partners.append((r,nc,n['color']))
    for r,c,col in partners:
        for dr,dc in ((-1,-1),(-1,1),(0,0),(1,-1),(1,1)): g[r+dr][c+dc]=col
    return g

